2:     double chiSquare = 0.0;
3:     for (int i = 0; i < residuals.length; i++) {
4:         chiSquare += residualsWeights[i] * residuals[i] * residuals[i];
5:     }
6:     return chiSquare;
7: }

8: public double getRMS() {
